    constructor(C _c) { c = _c; }
    function run(bytes32 g, uint amt) public payable {
        require(amt == 1 ether);
        require(address(this).balance >= amt);
        // Set up state: lock in a guess (top-level call).
        c.lockInGuess{value: amt}(g);
        uint before = address(c).balance;
        // settle() before the target block has passed must revert.
        bool reverted;
        try c.settle() { reverted = false; }
        catch { reverted = true; }
        assert(reverted && address(c).balance == before);
    }
    receive() external payable {}
