contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bytes32 g, uint amt) public payable {
        // A mis-funded lockInGuess must revert without locking in anything.
        require(amt != 1 ether);
        require(address(this).balance >= amt);
        uint before = address(c).balance;
        bool reverted;
        try c.lockInGuess{value: amt}(g) { reverted = false; }
        catch { reverted = true; }
        // The guess slot must still be free: a correctly funded lockInGuess now succeeds.
        c.lockInGuess{value: 1 ether}(g);
        assert(reverted && address(c).balance == before + 1 ether);
    }
    receive() external payable {}
}

