contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= amount);
        c.lockInGuess{value: amount}(keccak256(abi.encodePacked("seed")));

        // settle() in the same block cannot succeed: block.number is not yet > locked block
        bool settleReverted;
        try c.settle() { settleReverted = false; } catch { settleReverted = true; }

        // a failed settle must not unlock the guess: re-locking must still revert
        bool relinkReverted;
        try c.lockInGuess{value: amount}(keccak256(abi.encodePacked("other"))) { relinkReverted = false; } catch { relinkReverted = true; }

        assert(settleReverted && relinkReverted && address(c).balance == 1 ether);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        // Fresh C: no guess has ever been locked, so settle() must revert
        // and must not move any Ether out of c.
        uint balBefore = address(c).balance;

        bool settleReverted;
        try c.settle() { settleReverted = false; } catch { settleReverted = true; }

        assert(settleReverted && address(c).balance == balBefore && amount == amount);
    }

    receive() external payable {}
}
